CREATE TABLE credit_union_settings(id text PRIMARY KEY,name text NOT NULL,mapping jsonb NOT NULL,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,identity_id text UNIQUE,email text UNIQUE NOT NULL CHECK(email=lower(email)),credit_union_id text REFERENCES credit_union_settings(id),role text NOT NULL CHECK(role IN ('owner','admin','user')),active boolean NOT NULL DEFAULT true,settings jsonb NOT NULL DEFAULT '{"defaultWorkspace":"overview"}',updated_at timestamptz NOT NULL DEFAULT now(),CHECK(role='owner' OR credit_union_id IS NOT NULL));
CREATE TABLE activity_log(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),credit_union_id text REFERENCES credit_union_settings(id),action text NOT NULL,outcome text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX activity_union_date ON activity_log(credit_union_id,id DESC);
CREATE FUNCTION prevent_activity_changes() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Activity log is append-only'; END $$;
CREATE TRIGGER activity_append_only BEFORE UPDATE OR DELETE ON activity_log FOR EACH ROW EXECUTE FUNCTION prevent_activity_changes();
